'use strict';
(function(){
const host=document.getElementById('flightView'),notice=document.getElementById('viewStatus');
try{
 if(!window.THREE||!window.ViewTiles)throw Error('渲染库未加载');
 const T=THREE,scene=new T.Scene();scene.background=new T.Color('#b7cbd0');scene.fog=new T.Fog('#b7cbd0',850,1600);
 const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true,powerPreference:'high-performance'});
 renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','高清航空影像贴图的第一人称飞行仿真');
 const camera=new T.PerspectiveCamera(68,1,1,2200),loader=new T.TextureLoader();loader.setCrossOrigin('anonymous');
 const trafficModel=new T.Group(),mat=new T.MeshBasicMaterial({color:'#ff583e'});for(const angle of [0,Math.PI/2]){const arm=new T.Mesh(new T.BoxGeometry(2.4,.25,.25),mat);arm.rotation.y=angle;trafficModel.add(arm)}trafficModel.add(new T.Mesh(new T.SphereGeometry(.5,12,8),mat));trafficModel.visible=false;scene.add(trafficModel);const bodyVolume=new T.Mesh(new T.SphereGeometry(Collision.radius,16,12),new T.MeshBasicMaterial({color:'#ff9d76',wireframe:true,transparent:true,opacity:.5}));trafficModel.add(bodyVolume);for(const b of Collision.buildings){const geo=new T.BoxGeometry(b.w,b.h,b.d),mesh=new T.Mesh(geo,new T.MeshBasicMaterial({color:'#8796a0'}));mesh.position.set(b.x-450,b.h/2,b.y-330);scene.add(mesh);const edges=new T.LineSegments(new T.EdgesGeometry(geo),new T.LineBasicMaterial({color:'#d3e0e6'}));edges.position.copy(mesh.position);scene.add(edges)}
 const cache=new Map(),MAX_CACHE=240,MAX_REQUESTS=8,anisotropy=renderer.capabilities.getMaxAnisotropy();
 let wanted=[],wantedKeys=new Set(),inflight=0,sequence=0,state={x:420,y:500,heading:0,altitude:60,status:'ready'},yaw=0,pitch=38,cameraYawOffset=0,focalLength=18,contextLost=false,lastPlan=0,viewDrag=null;
 function status(){const near=wanted.filter(t=>t.z===20),done=near.filter(t=>cache.get(t.key)?.status==='ready').length,failed=near.some(t=>cache.get(t.key)?.status==='failed');notice.textContent=done===near.length?'HD · 高清航空影像 / FPV 仿真':failed?'高清影像部分加载失败 · 使用已有底图':`高清影像加载中 ${done}/${near.length} · FPV 仿真`;host.dataset.hdLoaded=String(done);host.dataset.hdTotal=String(near.length);host.dataset.cachedTiles=String(cache.size)}
 function trim(){if(cache.size<=MAX_CACHE)return;const unused=[...cache.entries()].filter(([key,v])=>!wantedKeys.has(key)&&v.status!=='loading').sort((a,b)=>a[1].used-b[1].used);for(const [key,v] of unused){if(cache.size<=MAX_CACHE)break;if(v.mesh){scene.remove(v.mesh);v.mesh.material.map?.dispose();v.mesh.material.dispose();v.mesh.geometry.dispose()}cache.delete(key)}}
 function pump(){if(contextLost)return;for(const tile of wanted){if(inflight>=MAX_REQUESTS)break;const old=cache.get(tile.key);if(old&&!(old.status==='failed'&&old.attempts<2&&performance.now()-old.failedAt>15000))continue;
  const entry={status:'loading',used:sequence,attempts:(old?.attempts||0)+1};cache.set(tile.key,entry);inflight++;
  loader.load(`https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.swissimage/default/current/3857/${tile.key}.jpeg`,texture=>{
   texture.colorSpace=T.SRGBColorSpace;texture.anisotropy=anisotropy;texture.minFilter=T.LinearMipmapLinearFilter;texture.magFilter=T.LinearFilter;
   const mesh=new T.Mesh(new T.PlaneGeometry(tile.size+.015,tile.size+.015),new T.MeshBasicMaterial({map:texture}));mesh.rotation.x=-Math.PI/2;mesh.position.set(tile.worldX,(tile.z-17)*.04,tile.worldY);scene.add(mesh);entry.mesh=mesh;entry.status='ready';inflight--;trim();status();pump();
  },undefined,()=>{entry.status='failed';entry.failedAt=performance.now();inflight--;status();pump()});
 }}
 function plan(){sequence++;wanted=ViewTiles.requests({...state,heading:yaw*180/Math.PI},pitch);wantedKeys=new Set(wanted.map(t=>t.key));for(const t of wanted){const hit=cache.get(t.key);if(hit)hit.used=sequence}trim();status();pump()}
 const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
 const focalToFov=mm=>2*Math.atan(12/mm)*180/Math.PI;
 function cameraPose(){return{yawOffset:cameraYawOffset,pitch,focalLength,fov:focalToFov(focalLength)}}
 function setCamera(next={},notify=false){if(Number.isFinite(Number(next.yawOffset)))cameraYawOffset=((Number(next.yawOffset)+540)%360)-180;if(Number.isFinite(Number(next.pitch)))pitch=clamp(Number(next.pitch),-75,85);if(Number.isFinite(Number(next.focalLength)))focalLength=clamp(Number(next.focalLength),8,55);camera.fov=focalToFov(focalLength);camera.updateProjectionMatrix();lastPlan=0;if(notify)window.dispatchEvent(new CustomEvent('uav-camera-change',{detail:{...cameraPose(),final:!!next.final,source:next.source||'control'}}));return cameraPose()}
 setCamera({focalLength});
 window.flightView={update:s=>{state=s},pitch:v=>setCamera({pitch:v}),setCamera,nudgeCamera:(yawDelta=0,pitchDelta=0)=>setCamera({yawOffset:cameraYawOffset+Number(yawDelta),pitch:pitch+Number(pitchDelta),source:'button'},true),getCamera:cameraPose,capture:()=>renderer.domElement.toDataURL('image/png')};
 function resize(){const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(host);resize();
 function frame(now){requestAnimationFrame(frame);if(contextLost)return;const desired=(state.heading+cameraYawOffset)*Math.PI/180,delta=Math.atan2(Math.sin(desired-yaw),Math.cos(desired-yaw));yaw+=delta*.06;camera.position.set(state.x-450,state.altitude,state.y-330);camera.lookAt(camera.position.x+Math.sin(yaw)*100,camera.position.y-Math.tan(pitch*Math.PI/180)*100,camera.position.z-Math.cos(yaw)*100);if(now-lastPlan>450){plan();lastPlan=now}trafficModel.visible=!!state.traffic;const marker=document.getElementById('trafficMarker');if(marker)marker.hidden=!state.traffic;if(state.traffic){trafficModel.position.set(state.traffic.x-450,state.traffic.altitude,state.traffic.y-330);camera.updateMatrixWorld();const projected=trafficModel.position.clone().project(camera),front=projected.z<1;if(marker){marker.style.left=Math.max(5,Math.min(73,(projected.x*.5+.5)*100))+'%';marker.style.top=Math.max(20,Math.min(70,(-projected.y*.5+.5)*100))+'%';marker.textContent=front&&Math.abs(projected.x)<1&&Math.abs(projected.y)<1?'✈ 移动目标':'↗ 移动目标（画面外）'}}renderer.render(scene,camera)}plan();requestAnimationFrame(frame);
 renderer.domElement.addEventListener('pointerdown',e=>{if(state.status!=='photo'||e.button!==0)return;e.preventDefault();viewDrag={id:e.pointerId,x:e.clientX,y:e.clientY,start:cameraPose()};renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.classList.add('camera-dragging')});
 renderer.domElement.addEventListener('pointermove',e=>{if(viewDrag?.id!==e.pointerId)return;e.preventDefault();setCamera({yawOffset:viewDrag.start.yawOffset-(e.clientX-viewDrag.x)*.22,pitch:viewDrag.start.pitch-(e.clientY-viewDrag.y)*.16,source:'drag'},true)});
 function endViewDrag(e){if(viewDrag?.id!==e.pointerId)return;setCamera({...cameraPose(),final:true,source:'drag'},true);viewDrag=null;renderer.domElement.classList.remove('camera-dragging')}
 renderer.domElement.addEventListener('pointerup',endViewDrag);renderer.domElement.addEventListener('pointercancel',endViewDrag);renderer.domElement.addEventListener('lostpointercapture',endViewDrag);
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();contextLost=true;notice.textContent='飞行视图暂不可用，请使用地图';document.body.classList.add('map-expanded')});
}catch(e){notice.textContent='此设备暂不支持飞行视图，已显示地图';document.body.classList.add('map-expanded')}
})();

